import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import chalk from 'chalk';
import ora from '../ui/spinner.js';
import { gitHubChildEnv, gitProcessEnv, locateGitHubCli } from '../github/gh.js';
import { registerCommand, type CommandContext } from './registry.js';

const exec = promisify(execFile);

export async function runPullRequest(args: string, ctx: CommandContext) {
  const signal = ctx.toolContext?.abortSignal;
  const run = (file: string, argv: string[]) => exec(file, argv, { cwd: ctx.cwd, encoding: 'utf8', timeout: 30_000, maxBuffer: 4 * 1024 * 1024, windowsHide: true, signal, env: file === 'git' ? gitProcessEnv() : gitHubChildEnv() });
  const git = async (argv: string[]) => (await run('git', argv)).stdout.trim();
  const optionalGit = (argv: string[]) => git(argv).catch(() => { signal?.throwIfAborted(); return ''; });
  try {
    const branch = await optionalGit(['branch', '--show-current']);
    if (!branch) { ctx.log('Not a Git repository or not on a branch.'); return; }
    const gh = await locateGitHubCli();
    if (!gh) { ctx.log('GitHub CLI is missing. Run notch github login to install it and sign in.'); return; }
    const baseBranch = (await run(gh, ['repo', 'view', '--json', 'defaultBranchRef', '--jq', '.defaultBranchRef.name'])).stdout.trim();
    if (!baseBranch || baseBranch === 'null') { ctx.log('The repository has no default branch. Push an initial commit first.'); return; }
    if (branch === baseBranch) { ctx.log(`You are on ${baseBranch}. Switch to a feature branch first.`); return; }
    const base = await optionalGit(['rev-parse', '--verify', `refs/remotes/origin/${baseBranch}`]) ? `refs/remotes/origin/${baseBranch}` : baseBranch;
    const stat = await git(['diff', `${base}...HEAD`, '--stat']);
    const log = await git(['log', `${base}..HEAD`, '--oneline']);
    if (!log) { ctx.log('No commits ahead of the base branch.'); return; }
    ctx.log(`Branch: ${branch} → ${baseBranch}\nCommits:\n${log}\nFiles:\n${stat}`);
    let title = args.trim();
    let body = 'Auto-generated by Notch CLI';
    if (!title) {
      const diff = await git(['diff', `${base}...HEAD`]);
      const prompt = `Generate a GitHub pull request title and body for these changes.\nBranch: ${branch} → ${baseBranch}\nCommits:\n${log}\nFiles:\n${stat}\nDiff:\n${diff.slice(0, 30_000)}\nReply as TITLE: <title under 72 characters> then BODY: followed by a summary and changes.`;
      const spinner = ora('Generating PR description...').start();
      let response: string;
      try { response = await ctx.runPrompt(prompt, [{ role: 'user', content: prompt }]); }
      finally { spinner.stop(); }
      title = response.match(/TITLE:\s*(.+)/)?.[1]?.trim() || `${branch}: changes from Notch`;
      body = response.match(/BODY:\s*([\s\S]+)/)?.[1]?.trim() || response;
      const confirm = ctx.confirm || ctx.toolContext?.confirm;
      let approved = false;
      if (confirm) approved = await confirm(`Push ${branch} and create PR \"${title}\"?\n${body}`);
      else {
        const { createInterface } = await import('node:readline/promises');
        const readline = createInterface({ input: process.stdin, output: process.stdout });
        try { approved = /^y(?:es)?$/i.test((await readline.question(`Push branch and create PR \"${title}\"? [y/N] `)).trim()); }
        finally { readline.close(); }
      }
      if (!approved) { ctx.log('PR cancelled. Nothing was pushed.'); return; }
    }
    signal?.throwIfAborted();
    const upstream = await optionalGit(['rev-parse', '--abbrev-ref', '@{upstream}']);
    // An upstream can exist while newer commits are still local.
    if (upstream) await git(['push']);
    else await git(['push', '-u', 'origin', 'HEAD']);
    const file = path.join(os.tmpdir(), `notch-pr-${crypto.randomUUID()}.txt`);
    try {
      await fs.writeFile(file, body, { mode: 0o600 });
      const result = await run(gh, ['pr', 'create', '--title', title, '--body-file', file, '--base', baseBranch]);
      ctx.log(chalk.green(result.stdout.trim()));
    } finally { await fs.unlink(file).catch(() => {}); }
  } catch (error) {
    ctx.log(signal?.aborted ? 'PR creation cancelled.' : `PR creation failed: ${(error as Error).message}`);
  }
}

registerCommand('/pr', runPullRequest);
